using System;using UnityEngine;using UnityEngine.InputSystem;
[DefaultExecutionOrder(-700)]public sealed class TrainingSession:MonoBehaviour {
 public enum StartPosition {Left,Center,Right}public enum DummyGuard {None,Guard,FD,AlwaysFD}
 public TrainingOverlay owner;public TrainingFighter first,second;public TrainingDummy dummy;
 public TrainingPlayerSettings firstSettings=new TrainingPlayerSettings(),secondSettings=new TrainingPlayerSettings();public StartPosition startPosition=StartPosition.Center;public DummyGuard guardMode;[Range(0,10)]public int dummyJG;
 public readonly TrainingRecorder Recorder=new TrainingRecorder();readonly TrainingRecoveryClock recovery1=new TrainingRecoveryClock(),recovery2=new TrainingRecoveryClock();TrainingInputFrame firstFrame,secondFrame;TrainingRecorder.Mode previousMode;bool routingControlled;bool resetPending,recordPending,playPending,resetting;public string Notice{get;private set;}="";public bool Resetting=>resetting;
 public void Configure(TrainingOverlay hud){owner=hud;first=hud.player;second=first.opponent;dummy=hud.dummy;first.TrainingSession=second.TrainingSession=this;recovery1.Rebase(first.Health);recovery2.Rebase(second.Health);var after=gameObject.GetComponent<TrainingSessionAfterTick>();if(after==null)after=gameObject.AddComponent<TrainingSessionAfterTick>();after.owner=this;}
 public TrainingPlayerSettings Settings(int player)=>player==0?firstSettings:secondSettings;
 public TrainingFighter InputTargetFor(TrainingFighter source)=>source==first&&Recorder.State==TrainingRecorder.Mode.Recording?second:source;
 public bool AutoDummy=>second!=null&&dummy!=null&&second.inputSourceBehaviour==dummy&&owner!=null&&!owner.SecondPlayerControlled&&!routingControlled&&Recorder.State!=TrainingRecorder.Mode.Recording&&Recorder.State!=TrainingRecorder.Mode.Playback;
 public bool HoldDummyPosition(TrainingFighter actor)=>actor==second&&AutoDummy&&secondFrame.FdHeld;
 public bool SuppressDummyReaction(TrainingFighter actor)=>actor==second&&!AutoDummy;
 public int? DummyJGFor(TrainingFighter actor)=>actor==second&&AutoDummy&&guardMode!=DummyGuard.None?dummyJG:(int?)null;
 public void HPAssigned(TrainingFighter actor){if(actor==first){recovery1.Rebase(actor.Health);owner?.MatchDisplay?.SecondAttack.RebaseHP(actor.Health);}else if(actor==second){recovery2.Rebase(actor.Health);owner?.MatchDisplay?.FirstAttack.RebaseHP(actor.Health);}}
 public void SetHP(int player,int percent){var s=Settings(player);s.hpPercent=Mathf.Clamp(percent,1,100);var f=player==0?first:second;f.SetTrainingHP(f.definition.maxHealth*s.hpPercent/100f);(player==0?recovery1:recovery2).Rebase(f.Health);}
 public bool SetTG(int player,int value){var s=Settings(player);s.tg=Mathf.Clamp(value,-200,200);(player==0?first:second).Tension.SetTrainingGauge(s.tg);Notice="";return true;}
 public void SetFixed(int player,bool value){Settings(player).fixedTG=value;(player==0?first:second).Tension.Fixed=value;}
 public void RequestReset()=>resetPending=true;public void RequestRecord()=>recordPending=true;public void RequestPlay()=>playPending=true;
 void Update(){if(owner==null||owner.OptionVisible||!Application.isFocused)return;var k=Keyboard.current;if(k==null)return;if(k.leftCtrlKey.wasPressedThisFrame||k.rightCtrlKey.wasPressedThisFrame)RequestReset();if(k.rKey.wasPressedThisFrame)RequestRecord();if(k.pKey.wasPressedThisFrame)RequestPlay();}
 void Boundary(){first.ClearTrainingInputBoundary();second.ClearTrainingInputBoundary();first.GetComponent<TrainingControls>()?.SetOptionBlocked(false);second.GetComponent<TrainingSecondPlayerControls>()?.SetOptionBlocked(false);firstFrame=secondFrame=default;}
 public void MenuOpened(){recordPending=playPending=resetPending=false;Recorder.Cancel(true);Boundary();}
 public void ResetConfigured(){resetting=true;try{Recorder.Cancel(false);recordPending=playPending=resetPending=false;Boundary();if(first.CombatV01!=null)first.CombatV01.ResetTest();else first.ResetTraining();float middle=startPosition==StartPosition.Left?-3.7f:startPosition==StartPosition.Right?3.7f:0;Place(first,middle-.8f);Place(second,middle+.8f);first.RefreshTrainingFacing();second.RefreshTrainingFacing();first.CameraBounds?.SnapFraming();SetHP(0,firstSettings.hpPercent);SetHP(1,secondSettings.hpPercent);SetTG(0,firstSettings.tg);SetTG(1,secondSettings.tg);SetFixed(0,firstSettings.fixedTG);SetFixed(1,secondSettings.fixedTG);Notice="Reset configured position / HP / TG";}finally{resetting=false;}}
 static void Place(TrainingFighter f,float x){f.GetComponent<TrainingMotor2D>().Teleport(new Vector2(x,.01f));}
 public TrainingInputFrame ReadFor(TrainingFighter fighter)=>fighter==first?firstFrame:secondFrame;
 void FixedUpdate(){if(first==null||second==null||owner==null||owner.OptionVisible)return;if(resetPending){ResetConfigured();return;}if(recordPending){Recorder.RecordKey();recordPending=false;}if(playPending){Recorder.PlayKey();playPending=false;}var mode=Recorder.State;if(previousMode!=mode){Boundary();previousMode=mode;}var live=(first.inputSourceBehaviour as ITrainingInputSource)?.ReadInput()??default;if(live.Reset){ResetConfigured();return;}if(live.ToggleOpponentGuard){guardMode=guardMode==DummyGuard.None?DummyGuard.Guard:DummyGuard.None;}live=TrainingRecorder.Logical(live);routingControlled=mode==TrainingRecorder.Mode.Recording||mode==TrainingRecorder.Mode.Playback;var recorded=Recorder.Tick(live);
 firstFrame=mode==TrainingRecorder.Mode.Countdown||mode==TrainingRecorder.Mode.Recording?default:live;
 if(mode==TrainingRecorder.Mode.Recording||mode==TrainingRecorder.Mode.Playback)secondFrame=recorded;else if(mode==TrainingRecorder.Mode.Countdown)secondFrame=default;else secondFrame=(second.inputSourceBehaviour as ITrainingInputSource)?.ReadInput()??default;
 if(AutoDummy){second.Guarding=guardMode!=DummyGuard.None;bool fd=guardMode==DummyGuard.AlwaysFD||guardMode==DummyGuard.FD&&first.IsGuardThreatMotion;if(fd){secondFrame.Movement.x=-second.OpponentDirectionForGuard;secondFrame.FdHeld=true;}}else if(mode==TrainingRecorder.Mode.Recording||mode==TrainingRecorder.Mode.Playback)second.Guarding=false;
 }
 public void AfterTick(){if(first==null||owner==null||owner.OptionVisible)return;Recover(first,firstSettings,recovery1);Recover(second,secondSettings,recovery2);owner.CaptureCommandDisplays();}
 static void Recover(TrainingFighter actor,TrainingPlayerSettings settings,TrainingRecoveryClock clock){float hp=actor.definition.maxHealth*settings.hpPercent/100f;bool busy=actor.TrainingRecoveryBusy;if(clock.Tick(actor.Health,hp,settings.recover,busy,Time.fixedDeltaTime))actor.SetTrainingHP(hp);}
 void OnDestroy(){if(first!=null&&first.TrainingSession==this){first.TrainingSession=null;first.Tension.Fixed=false;}if(second!=null&&second.TrainingSession==this){second.TrainingSession=null;second.Tension.Fixed=false;}}
}
